-- Local synthetic integration regression: losing technician role takes effect
-- for the same Auth session even when old ticket/appointment assignments remain.
DO $$ BEGIN IF inet_server_addr() IS DISTINCT FROM '127.0.0.1'::inet THEN RAISE EXCEPTION 'Local test server required'; END IF; END $$;
BEGIN;
INSERT INTO auth.sessions(id,user_id,created_at) VALUES('11000000-0000-4000-8000-000000000101','10000000-0000-4000-8000-000000000001',clock_timestamp());
SET ROLE authenticated;
SELECT test_auth.login(3,'20000000-0000-4000-8000-000000000002');
SELECT public.start_ticket_appointment('50000000-0000-4000-8000-000000000005','analysis');
SELECT test_auth.assert((SELECT status='in_progress' AND actual_start IS NOT NULL FROM public.ticket_appointments WHERE ticket_id='50000000-0000-4000-8000-000000000005'),'assigned technician can start appointment');
SELECT public.complete_ticket_appointment('50000000-0000-4000-8000-000000000005','analysis');
SELECT test_auth.assert((SELECT status='completed' AND actual_end IS NOT NULL FROM public.ticket_appointments WHERE ticket_id='50000000-0000-4000-8000-000000000005'),'assigned technician can complete appointment');
RESET ROLE;
SELECT test_auth.login(2,'20000000-0000-4000-8000-000000000002');
UPDATE public.ticket_appointments SET status='scheduled',actual_start=NULL,actual_end=NULL WHERE ticket_id='50000000-0000-4000-8000-000000000005';
UPDATE public.tickets SET status='Andamento Reparo',budget_status='Aprovado',repair_start_at=NULL,repair_paused_at=NULL,repair_end_at=NULL,repair_successful=NULL,parts_status=NULL WHERE id='50000000-0000-4000-8000-000000000005';
SET ROLE authenticated;
SELECT test_auth.login(3,'20000000-0000-4000-8000-000000000002');
SELECT public.start_repair_timer('50000000-0000-4000-8000-000000000005');
SELECT test_auth.assert((SELECT repair_start_at IS NOT NULL FROM public.tickets WHERE id='50000000-0000-4000-8000-000000000005'),'assigned technician can start repair');
SELECT test_auth.login(1,'20000000-0000-4000-8000-000000000002','11000000-0000-4000-8000-000000000101');
SELECT test_auth.assert((SELECT is_technician AND NOT is_admin FROM public.get_current_actor_context()),'foreign technician has valid current session');
SELECT test_auth.expect_error('SELECT public.start_ticket_appointment(''50000000-0000-4000-8000-000000000005'',''analysis'')','P0001');
SELECT test_auth.expect_error('SELECT public.complete_ticket_appointment(''50000000-0000-4000-8000-000000000005'',''analysis'')','P0001');
RESET ROLE;
SELECT test_auth.login(2,'20000000-0000-4000-8000-000000000002');
UPDATE public.tickets SET repair_start_at=NULL WHERE id='50000000-0000-4000-8000-000000000005';
SET ROLE authenticated;
SELECT test_auth.login(1,'20000000-0000-4000-8000-000000000002','11000000-0000-4000-8000-000000000101');
SELECT test_auth.expect_error('SELECT public.start_repair_timer(''50000000-0000-4000-8000-000000000005'')','P0001');
SELECT test_auth.login(2,'20000000-0000-4000-8000-000000000002');
SELECT public.update_employee_access((SELECT id FROM test_auth.fixture WHERE name='rejoined_employee'),'Rejoining technician',ARRAY['tester']);
SELECT test_auth.login(3,'20000000-0000-4000-8000-000000000002');
SELECT test_auth.assert((SELECT NOT is_technician AND NOT is_admin AND actor_roles=ARRAY['tester'] FROM public.get_current_actor_context()),'same session sees current tester role');
SELECT test_auth.expect_error('SELECT public.start_ticket_appointment(''50000000-0000-4000-8000-000000000005'',''analysis'')','P0001');
SELECT test_auth.expect_error('SELECT public.complete_ticket_appointment(''50000000-0000-4000-8000-000000000005'',''analysis'')','P0001');
SELECT test_auth.expect_error('SELECT public.start_repair_timer(''50000000-0000-4000-8000-000000000005'')','P0001');
SELECT set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb || '{"user_metadata":{"roles":["admin","tecnico"]},"roles":["admin","tecnico"],"is_admin":true}'::jsonb)::text,false);
SELECT test_auth.expect_error('SELECT public.start_ticket_appointment(''50000000-0000-4000-8000-000000000005'',''analysis'')','P0001');
SELECT test_auth.expect_error('SELECT public.complete_ticket_appointment(''50000000-0000-4000-8000-000000000005'',''analysis'')','P0001');
SELECT test_auth.expect_error('SELECT public.start_repair_timer(''50000000-0000-4000-8000-000000000005'')','P0001');
RESET ROLE;
SELECT test_auth.assert((SELECT status='scheduled' AND actual_start IS NULL AND actual_end IS NULL FROM public.ticket_appointments WHERE ticket_id='50000000-0000-4000-8000-000000000005'),'denied appointment calls change nothing');
SELECT test_auth.assert((SELECT repair_start_at IS NULL FROM public.tickets WHERE id='50000000-0000-4000-8000-000000000005'),'denied repair calls change nothing');
SET ROLE authenticated;
SELECT test_auth.login(4,'20000000-0000-4000-8000-000000000002');
SELECT public.start_ticket_appointment('50000000-0000-4000-8000-000000000005','analysis');
SELECT public.complete_ticket_appointment('50000000-0000-4000-8000-000000000005','analysis');
SELECT public.start_repair_timer('50000000-0000-4000-8000-000000000005');
RESET ROLE;
SELECT test_auth.assert((SELECT status='completed' AND actual_start IS NOT NULL AND actual_end IS NOT NULL FROM public.ticket_appointments WHERE ticket_id='50000000-0000-4000-8000-000000000005'),'attendant appointment actions preserved');
SELECT test_auth.assert((SELECT repair_start_at IS NOT NULL FROM public.tickets WHERE id='50000000-0000-4000-8000-000000000005'),'attendant repair start preserved');
SELECT test_auth.login(2,'20000000-0000-4000-8000-000000000002');
UPDATE public.ticket_appointments SET status='scheduled',actual_start=NULL,actual_end=NULL WHERE ticket_id='50000000-0000-4000-8000-000000000005';
UPDATE public.tickets SET repair_start_at=NULL WHERE id='50000000-0000-4000-8000-000000000005';
SET ROLE authenticated;
SELECT test_auth.login(2,'20000000-0000-4000-8000-000000000002');
SELECT public.start_ticket_appointment('50000000-0000-4000-8000-000000000005','analysis');
SELECT public.complete_ticket_appointment('50000000-0000-4000-8000-000000000005','analysis');
SELECT public.start_repair_timer('50000000-0000-4000-8000-000000000005');
RESET ROLE;
SELECT test_auth.assert((SELECT status='completed' FROM public.ticket_appointments WHERE ticket_id='50000000-0000-4000-8000-000000000005'),'owner administration preserved');
SELECT test_auth.assert((SELECT repair_start_at IS NOT NULL FROM public.tickets WHERE id='50000000-0000-4000-8000-000000000005'),'owner repair start preserved');
ROLLBACK;
SELECT 'PASS: former technician denied, unchanged session and forged metadata denied, own technician/owner/attendant preserved, foreign assignment denied' as result;
